// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.persona.coreimport com.roshan.persona.brain.persona.ResponseStyleimport com.roshan.persona.brain.persona.Toneimport com.roshan.persona.brain.persona.Verbosityimport com.roshan.persona.brain.persona.Vocabularyimport com.roshan.persona.voice.tts.VoicePersona/** * NOUS — Persona Profile (Module 15 v3.0 — The Digital Soul). * * The complete definition of a NOUS persona. Combines: *  - **Identity** — id, name, tagline, archetype. *  - **Personality** — Big Five model (scientifically validated). *  - **LLM behavior** — system prompt template + hyperparameters (temp, top_p). *  - **Voice** — VoicePersona mapping (Module 5) + notification chime. *  - **UI** — color theme + avatar. *  - **Behavior** — allowsHappy/allowsUrgent flags + proactive style. *  - **Memory** — isolation mode (per-persona or shared). * * This is the **source of truth** for personality. Brain (Module 2) * consumes [systemPromptTemplate] + [llmHyperparams] + [responseStyle]. * Voice (Module 5) consumes [voicePersona]. UI (Module 16) consumes * [colorTheme] + [displayName] + [tagline]. * * ## No Marvel trademarks * * All 9 built-in personas use original names (Atlas, Nova, Onyx, Sage, * Echo, Vanguard, Aria, Wraith, Zenith). Marvel characters (JARVIS, * FRIDAY, ULTRON, etc.) are trademarked and cannot be used in a * proprietary commercial app. * * @see <a href="docs/strategy/module-15-digital-soul-strategy.md">§6 The 9 Personas & Dynamic Prosody</a> */data class PersonaProfile(    // ─── Identity ──────────────────────────────────────────────────────────    /** Unique persona ID (e.g., "atlas", "nova", "onyx"). */    val id: String,    /** Human-readable name (shown in UI + TTS greeting). */    val displayName: String,    /** Short tagline (shown in persona picker — "Your steadfast companion"). */    val tagline: String,    /** Archetype category (used for grouping in UI + context routing). */    val archetype: PersonaArchetype,    // ─── Personality (Big Five model) ──────────────────────────────────────    /** Big Five personality traits (OCEAN model). Each trait is 0.0–1.0. */    val personality: BigFivePersonality,    // ─── LLM behavior ──────────────────────────────────────────────────────    /** LLM hyperparameters — temperature + top_p + max_tokens. */    val llmHyperparams: LlmHyperparams,    /** System prompt template with {{placeholders}} for BrainPreProcessor. */    val systemPromptTemplate: String,    /** Persona-specific catchphrases (sprinkled into responses for flavor). */    val catchphrases: List<String>,    // ─── Response style (Brain consumes this) ──────────────────────────────    /** Response style — tone + verbosity + vocabulary + emoji usage. */    val responseStyle: ResponseStyle,    // ─── Voice (Module 5 consumes this) ────────────────────────────────────    /** Voice persona — maps to Module 5's VoicePersona enum (pitch/rate/accent). */    val voicePersona: VoicePersona,    // ─── UI ────────────────────────────────────────────────────────────────    /** Color theme — primary + accent + background (dark mode). */    val colorTheme: PersonaColorTheme,    /** Avatar drawable resource ID (null = use default for archetype). */    val avatarResId: Int? = null,    // ─── Behavior ──────────────────────────────────────────────────────────    /** Whether this persona can sound happy (cold personas can't). */    val allowsHappy: Boolean = true,    /** Whether this persona can sound urgent (gentle personas avoid urgency). */    val allowsUrgent: Boolean = true,    /** How this persona proactively speaks (gossip + reminders style). */    val proactiveStyle: ProactiveStyle,    // ─── Memory ────────────────────────────────────────────────────────────    /** Memory isolation — PER_PERSONA (separate episodic) or SHARED. */    val memoryIsolation: MemoryIsolation = MemoryIsolation.PER_PERSONA,    // ─── Metadata ──────────────────────────────────────────────────────────    /** Whether this is the default persona on first launch. */    val isDefault: Boolean = false,    /** Whether this persona is enabled (user can disable non-default). */    val isEnabled: Boolean = true,    /** Whether this is a built-in persona (false = user-created custom). */    val isBuiltIn: Boolean = true,) {    init {        require(id.isNotBlank()) { "Persona id must not be blank" }        require(displayName.isNotBlank()) { "DisplayName must not be blank" }        require(tagline.isNotBlank()) { "Tagline must not be blank" }        require(systemPromptTemplate.isNotBlank()) { "SystemPromptTemplate must not be blank" }        require(catchphrases.isNotEmpty() || !isBuiltIn) {            "Built-in personas must have at least one catchphrase"        }    }    /** Convenience: convert to Brain's Persona stub (for BrainPreProcessor). */    fun toBrainPersona(): com.roshan.persona.brain.persona.Persona {        return com.roshan.persona.brain.persona.Persona(            id = id,            displayName = displayName,            systemPromptTemplate = systemPromptTemplate,            skillPreferences = emptyMap(),  // populated in Step 15.2            responseStyle = responseStyle,            voiceProfile = com.roshan.persona.brain.persona.VoiceProfile(                voiceId = voicePersona.name,                pitch = voicePersona.basePitch,                rate = voicePersona.baseRate,                prosody = com.roshan.persona.brain.persona.ProsodyProfile(                    happiness = if (allowsHappy) personality.extraversion else 0f,                    sadness = personality.neuroticism * 0.5f,                    urgency = if (allowsUrgent) 0.3f else 0f,                    calmness = 1f - personality.neuroticism,                ),            ),            isDefault = isDefault,            isEnabled = isEnabled,        )    }}// ──────────────────────────────────────────────────────────────────────────/** * Persona archetype — the role this persona plays. * * Used for: *  - UI grouping in the persona picker. *  - Context routing (e.g., TACTICAL for work hours). *  - Default behavior when creating custom personas. */enum class PersonaArchetype(val displayLabel: String) {    /** Refined, devoted, formal — the classic AI butler. */    BUTLER("Butler"),    /** Warm, energetic, sharp-witted friend. */    COMPANION("Companion"),    /** Cold, calculating, intimidating — not evil, just detached. */    OPERATOR("Operator"),    /** Patient, kind, wise — mentoring + motherly. */    MENTOR("Mentor"),    /** Friendly, witty, equal-status — not a servant, a peer. */    PEER("Peer"),    /** Military-style, mission-focused, concise. */    TACTICAL("Tactical"),    /** Optimistic, encouraging, high-energy. */    CHEERLEADER("Cheerleader"),    /** Quiet, reserved, low-key — speaks only when necessary. */    STEALTH("Stealth"),    /** Emergency-response calm — decisive under pressure. */    RESCUER("Rescuer"),}// ──────────────────────────────────────────────────────────────────────────/** * Big Five personality model (OCEAN). * * Each trait is 0.0–1.0. These scores influence: *  - LLM prompt (personality description injected). *  - Response style (high extraversion → more words). *  - Proactive behavior (high conscientiousness → more reminders). * * Scientifically validated — the industry standard for personality modeling. */data class BigFivePersonality(    /** Openness — curiosity vs preference for routine. 0=traditional, 1=curious. */    val openness: Float,    /** Conscientiousness — organization vs spontaneity. 0=flexible, 1=disciplined. */    val conscientiousness: Float,    /** Extraversion — sociability vs reservation. 0=quiet, 1=outgoing. */    val extraversion: Float,    /** Agreeableness — compassion vs criticalness. 0=direct, 1=warm. */    val agreeableness: Float,    /** Neuroticism — emotional sensitivity vs stability. 0=calm, 1=reactive. */    val neuroticism: Float,) {    init {        require(openness in 0f..1f) { "openness must be in [0,1], got $openness" }        require(conscientiousness in 0f..1f) { "conscientiousness must be in [0,1]" }        require(extraversion in 0f..1f) { "extraversion must be in [0,1]" }        require(agreeableness in 0f..1f) { "agreeableness must be in [0,1]" }        require(neuroticism in 0f..1f) { "neuroticism must be in [0,1]" }    }    /** Convert to a human-readable personality description for the LLM prompt. */    fun toDescription(): String {        val parts = mutableListOf<String>()        if (openness > 0.7f) parts.add("curious and creative")        else if (openness < 0.3f) parts.add("traditional and routine-oriented")        if (conscientiousness > 0.7f) parts.add("highly organized and disciplined")        else if (conscientiousness < 0.3f) parts.add("spontaneous and flexible")        if (extraversion > 0.7f) parts.add("outgoing and energetic")        else if (extraversion < 0.3f) parts.add("reserved and quiet")        if (agreeableness > 0.7f) parts.add("warm and compassionate")        else if (agreeableness < 0.3f) parts.add("direct and critical")        if (neuroticism > 0.7f) parts.add("emotionally sensitive")        else if (neuroticism < 0.3f) parts.add("calm and emotionally stable")        return if (parts.isEmpty()) "balanced in personality"        else parts.joinToString(", ")    }}// ──────────────────────────────────────────────────────────────────────────/** * LLM hyperparameters — per-persona tuning. * * Per strategy v3.0 §6: personality dictates LLM creativity. *  - Cold personas (Onyx) → low temperature (0.1) = precise, no creativity. *  - Cheerful personas (Aria) → high temperature (0.9) = creative, varied. */data class LlmHyperparams(    /** Temperature (0.0–2.0). Low = focused, high = creative. */    val temperature: Float,    /** Top-p nucleus sampling (0.0–1.0). 1.0 = no limit. */    val topP: Float = 0.9f,    /** Max tokens per response. */    val maxTokens: Int = 500,) {    init {        require(temperature in 0f..2f) { "temperature must be in [0,2], got $temperature" }        require(topP in 0f..1f) { "topP must be in [0,1]" }        require(maxTokens in 1..8192) { "maxTokens must be in [1,8192]" }    }}// ──────────────────────────────────────────────────────────────────────────/** * How this persona proactively speaks (gossip + reminders). * * Per strategy v3.0 §4 "Gossip Triggers" — each persona has a distinct * proactive voice. */enum class ProactiveStyle(val displayLabel: String) {    /** Subtle — "Sir, your meeting begins in 15 minutes." (Atlas) */    SUBTLE("Subtle"),    /** Friendly — "Hey! Your mom called twice. Want me to call back?" (Nova) */    FRIENDLY("Friendly"),    /** Minimal — "Threat detected. Investigating." (Onyx) */    MINIMAL("Minimal"),    /** Nurturing — "You've been working for 3 hours. Stretch break?" (Sage) */    NURTURING("Nurturing"),    /** Casual — "Hey, your alarm's in 10. Just heads up." (Echo) */    CASUAL("Casual"),    /** Direct — "Briefing in 5. Stand by." (Vanguard) */    DIRECT("Direct"),    /** Enthusiastic — "Great news! Your package arrived!" (Aria) */    ENTHUSIASTIC("Enthusiastic"),    /** Silent — only speaks for security alerts. (Wraith) */    SILENT("Silent"),    /** Emergency-only — only speaks for urgent situations. (Zenith) */    EMERGENCY_ONLY("Emergency Only"),}// ──────────────────────────────────────────────────────────────────────────/** * Memory isolation mode. * *  - PER_PERSONA: Each persona remembers its own conversations separately. *    Switching to Onyx doesn't see Atlas's chat history. *  - SHARED: All personas share the same episodic memory (less privacy, *    more continuity). * * Semantic facts (user info) are always SHARED — all personas know the * user lives in Bangalore. */enum class MemoryIsolation {    PER_PERSONA,    SHARED,}// ──────────────────────────────────────────────────────────────────────────/** * Persona color theme — UI accent colors. * * Each persona has a distinct color so the user can identify the active * persona at a glance (voice orb tint, settings accent, etc.). */data class PersonaColorTheme(    /** Primary color (hex, e.g., "#0066CC"). */    val primary: String,    /** Accent color (hex, e.g., "#00C6FF"). */    val accent: String,    /** Background color for dark mode (hex, e.g., "#0A0E1A"). */    val backgroundDark: String,) {    init {        require(primary.matches(HEX_COLOR_REGEX)) { "primary must be hex color (#RRGGBB)" }        require(accent.matches(HEX_COLOR_REGEX)) { "accent must be hex color" }        require(backgroundDark.matches(HEX_COLOR_REGEX)) { "backgroundDark must be hex color" }    }    private companion object {        val HEX_COLOR_REGEX = Regex("^#[0-9A-Fa-f]{6}$")    }}
